settings.liquid:
{%- comment -%}
CURVJEANS — Size Guide Section (Custom Liquid friendly)
- Paste into a Custom Liquid block on your PDP template.
- Clean, minimal chips with arrow nudge on hover.
- EN title auto-translates to NL/DE based on URL.
{%- endcomment -%}

<section class="cj-sg" aria-labelledby="cj-sg-title">
  <h2 id="cj-sg-title" class="cj-sg__title">Find Your Perfect Fit</h2>

  <nav class="cj-sg__list" aria-label="Size charts">
    <a class="cj-sg__item" href="https://curvjeans.com/pages/size-chart-curvjeans-relax-jeans">
      <span class="cj-sg__label">Relax</span><span class="cj-sg__arrow" aria-hidden="true">➝</span>
    </a>

    <a class="cj-sg__item" href="https://curvjeans.com/pages/size-chart-curvjeans-straight-jeans">
      <span class="cj-sg__label">Straight</span><span class="cj-sg__arrow" aria-hidden="true">➝</span>
    </a>

    <a class="cj-sg__item" href="/pages/size-chart-wide-leg">
      <span class="cj-sg__label">Wide Leg</span><span class="cj-sg__arrow" aria-hidden="true">➝</span>
    </a>

    <a class="cj-sg__item" href="https://curvjeans.com/pages/size-chart-shapewear">
      <span class="cj-sg__label">Shapewear</span><span class="cj-sg__arrow" aria-hidden="true">➝</span>
    </a>
  </nav>
</section>

<style>
  /* ---- Brand tokens ---- */
  .cj-sg{
    --sg-accent: #ff5189;   /* CURVJEANS pink */
    --sg-bg: #F8F9FA;       /* light grey used in quick menu */
    --sg-border: #EDEDED;
    --sg-text: #111;
    --sg-dim: #666;
    --sg-radius: 14px;
  }

  /* ---- Wrapper ---- */
  .cj-sg{
    max-width: 760px;
    margin: 0 auto;
    padding: 8px 0 20px;
  }

  .cj-sg__title{
    margin: 0 0 12px;
    font-size: clamp(22px, 4.5vw, 28px);
    font-weight: 800;
    line-height: 1.15;
    color: var(--sg-text);
    text-align: center;
    letter-spacing: .01em;
  }

  /* ---- List ---- */
  .cj-sg__list{
    display: grid;
    gap: 10px;
  }

  .cj-sg__item{
    display:flex; align-items:center; justify-content:space-between;
    padding: 14px 16px;
    border-radius: var(--sg-radius);
    background:#fff;
    border:1px solid var(--sg-border);
    color:var(--sg-text);
    text-decoration:none !important;
    /* hard reset any theme underline tricks */
    background-image:none !important; box-shadow:none !important;
  }
  .cj-sg__item *{ text-decoration:none !important; background-image:none !important; box-shadow:none !important; }

  .cj-sg__label{
    font-size:17px; font-weight:700; letter-spacing:.01em;
  }
  .cj-sg__arrow{
    font-size:18px; line-height:1; color:var(--sg-dim);
    transition: transform .12s ease, color .12s ease;
  }

  /* Hover/focus */
  .cj-sg__item:hover,
  .cj-sg__item:focus-visible{
    background: var(--sg-bg);
    border-color: var(--sg-accent);
    outline: none;
  }
  .cj-sg__item:hover .cj-sg__arrow,
  .cj-sg__item:focus-visible .cj-sg__arrow{
    transform: translateX(3px);
    color: var(--sg-accent);
  }

  /* Compact on mobile */
  @media (max-width: 600px){
    .cj-sg__item{ padding: 12px 14px; }
    .cj-sg__label{ font-size: 16px; }
  }

  /* Optional: two columns on large desktop */
  @media (min-width: 1100px){
    .cj-sg__list{ grid-template-columns: 1fr 1fr; }
  }

  /* Motion preference */
  @media (prefers-reduced-motion: reduce){
    .cj-sg__item, .cj-sg__arrow{ transition: none; }
  }
</style>

<script>
  // Lightweight i18n for the title (keeps labels as product names)
  document.addEventListener("DOMContentLoaded", function(){
    var t = document.getElementById("cj-sg-title");
    if(!t) return;
    var p = location.pathname;
    if (p.startsWith("/nl"))      t.textContent = "Vind jouw perfecte fit";
    else if (p.startsWith("/de")) t.textContent = "Finde deine perfekte Passform";
  });
</script>
